import collections

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    def parse_amount(amount_str: str) -> float:
        if not isinstance(amount_str, str):
            raise ValueError("Amount must be a string")
        # Remove currency symbols and thousands separators
        clean_str = amount_str.replace('$', '').replace(',', '').strip()
        return float(clean_str)

    # Store totals keyed by lowercase name
    totals = collections.defaultdict(float)
    # Store the original trimmed name for the first encounter of each customer
    name_map = {}

    for row in rows:
        raw_name = row.get("customer")
        raw_amount = row.get("amount")

        if not isinstance(raw_name, str) or not isinstance(raw_amount, str):
            continue

        trimmed_name = raw_name.strip()
        if not trimmed_name:
            continue

        try:
            amount = parse_amount(raw_amount)
            key = trimmed_name.lower()

            if key not in name_map:
                name_map[key] = trimmed_name

            totals[key] += amount
        except (ValueError, TypeError):
            continue

    # Prepare final list of (original_name, rounded_total)
    result = []
    for key, total in totals.items():
        result.append((name_map[key], round(total, 2)))

    # Sort by total descending, then name ascending
    result.sort(key=lambda x: (-x[1], x[0]))

    return result[:n]
